#!/usr/bin/env python3
"""Fill training feedback HWPX template using training_feedback.json.

Creates /root/training_feedback_ready.hwpx.

Notes:
- HWPX is a ZIP archive with XML content under Contents/.
- Placeholder tokens are written as {{key}}.
- Some HWPX writers split text across multiple <hp:t> tags; we merge adjacent
  <hp:t> elements inside a single <hp:run> so placeholders become contiguous.
- After replacement, we remove stale layout caches (<hp:lineSegArray> /
  <hp:linesegarray>) under paragraphs (<hp:p>) whose *visible text* changed.
"""

from __future__ import annotations

import json
import os
import re
import shutil
import zipfile
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, Iterable, List, Tuple

import xml.etree.ElementTree as ET
from xml.sax.saxutils import escape as xml_escape


ROOT = Path("/root")
TEMPLATE = ROOT / "training_feedback_template.hwpx"
JSON_PATH = ROOT / "training_feedback.json"
OUT_PATH = ROOT / "training_feedback_ready.hwpx"

WORK_DIR = Path("/tmp/hwpx_work")
VERIFY_DIR = Path("/tmp/hwpx_verify")


@dataclass
class XmlChangeReport:
    path: Path
    placeholders_before: List[str]
    placeholders_after: List[str]
    modified_paragraph_ids: List[str]


def extract_hwpx(src: Path, dst_dir: Path) -> None:
    shutil.rmtree(dst_dir, ignore_errors=True)
    dst_dir.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(src, "r") as z:
        z.extractall(dst_dir)


def repack_hwpx(src_dir: Path, out_zip: Path) -> None:
    if out_zip.exists():
        out_zip.unlink()
    with zipfile.ZipFile(out_zip, "w", compression=zipfile.ZIP_DEFLATED) as z:
        for root, _dirs, files in os.walk(src_dir):
            for name in files:
                fp = Path(root) / name
                arcname = fp.relative_to(src_dir).as_posix()
                z.write(fp, arcname)


_PLACEHOLDER_RE = re.compile(r"\{\{\s*([^}]+?)\s*\}\}")


def find_placeholders(xml_text: str) -> List[str]:
    return sorted({m.group(1) for m in _PLACEHOLDER_RE.finditer(xml_text)})


def merge_adjacent_hp_t_inside_runs(xml_text: str) -> str:
    """Merge adjacent <hp:t>...</hp:t> siblings within <hp:run> blocks.

    This turns patterns like:
      <hp:run>...<hp:t>{{</hp:t><hp:t>key}}</hp:t>...</hp:run>
    into:
      <hp:run>...<hp:t>{{key}}</hp:t>...</hp:run>

    We do not attempt full XML parsing here to minimize reserialization changes.
    """

    run_re = re.compile(r"(<hp:run\b[^>]*>)(.*?)(</hp:run>)", re.DOTALL)
    t_re = re.compile(r"<hp:t(\b[^>]*)>(.*?)</hp:t>", re.DOTALL)

    def merge_run_content(content: str) -> str:
        # Split into a token stream of hp:t elements and non-t text.
        parts: List[Tuple[str, str, str]] = []
        # Each item: (kind, attrs, payload) where kind is 't' or 'raw'
        pos = 0
        for m in t_re.finditer(content):
            if m.start() > pos:
                parts.append(("raw", "", content[pos : m.start()]))
            parts.append(("t", m.group(1), m.group(2)))
            pos = m.end()
        if pos < len(content):
            parts.append(("raw", "", content[pos:]))

        merged: List[str] = []
        i = 0
        while i < len(parts):
            kind, attrs, payload = parts[i]
            if kind != "t":
                merged.append(payload)
                i += 1
                continue

            # Merge consecutive t's (possibly separated by whitespace raw parts).
            texts = [payload]
            chosen_attrs = attrs  # keep the first one's attrs
            j = i + 1
            while j < len(parts):
                k2, a2, p2 = parts[j]
                if k2 == "raw" and p2.strip() == "":
                    # keep whitespace between tags (it is irrelevant inside runs)
                    j += 1
                    continue
                if k2 == "t":
                    texts.append(p2)
                    j += 1
                    continue
                break

            merged.append(f"<hp:t{chosen_attrs}>{''.join(texts)}</hp:t>")
            i = j

        return "".join(merged)

    def repl(m: re.Match) -> str:
        start, content, end = m.group(1), m.group(2), m.group(3)
        new_content = merge_run_content(content)
        return start + new_content + end

    return run_re.sub(repl, xml_text)


def transform_value(key: str, value: str) -> str:
    if key == "참석자수":
        digits = re.findall(r"\d+", str(value))
        return "".join(digits)

    if key == "만족도":
        # Expected formats like "4.5/5.0" or "4.5".
        m = re.search(r"(\d+(?:\.\d+)?)", str(value))
        score = float(m.group(1)) if m else 0.0
        return f"{score:.1f}점 (5.0점 만점)"

    if key == "종합의견":
        suffix = "후속 심화반 검토 요망."
        s = str(value)
        if s.endswith((" ", "\t", "\n")):
            return s + suffix
        return s + " " + suffix

    return str(value)


def replace_placeholders(xml_text: str, mapping: Dict[str, str]) -> str:
    out = xml_text
    for k, v in mapping.items():
        # Escape for XML text nodes.
        escaped = xml_escape(v)
        out = re.sub(r"\{\{\s*" + re.escape(k) + r"\s*\}\}", escaped, out)
    return out


def _local_name(tag: str) -> str:
    return tag.split("}", 1)[1] if "}" in tag else tag


def paragraph_visible_text(p_elem: ET.Element) -> str:
    # Join all text within hp:t descendants.
    texts: List[str] = []
    for node in p_elem.iter():
        if _local_name(node.tag) == "t":
            if node.text:
                texts.append(node.text)
    return "".join(texts)


def remove_line_seg_arrays_for_modified_paragraphs(
    before_xml: str, after_xml: str
) -> Tuple[str, List[str]]:
    """Remove <hp:lineSegArray>/<hp:linesegarray> from paragraphs whose visible text changed."""

    before_root = ET.fromstring(before_xml)
    after_root = ET.fromstring(after_xml)

    # Build map paragraph-id -> visible text for before.
    before_map: Dict[str, str] = {}
    for p in before_root.iter():
        if _local_name(p.tag) != "p":
            continue
        pid = p.attrib.get("id")
        if pid is None:
            continue
        before_map[pid] = paragraph_visible_text(p)

    modified_ids: List[str] = []

    for p in after_root.iter():
        if _local_name(p.tag) != "p":
            continue
        pid = p.attrib.get("id")
        if pid is None:
            continue
        before_text = before_map.get(pid)
        after_text = paragraph_visible_text(p)
        if before_text is None or before_text == after_text:
            continue

        # Remove any line seg arrays (case-insensitive local name match).
        removed_any = False
        for child in list(p):
            if _local_name(child.tag).lower() in {"linesegarray", "linesegarray"}:
                p.remove(child)
                removed_any = True
        if removed_any:
            modified_ids.append(pid)

    # Serialize back.
    xml_bytes = ET.tostring(after_root, encoding="utf-8", xml_declaration=True)
    return xml_bytes.decode("utf-8"), modified_ids


def process_xml_file(xml_path: Path, mapping: Dict[str, str]) -> XmlChangeReport:
    original = xml_path.read_text("utf-8")

    merged = merge_adjacent_hp_t_inside_runs(original)
    placeholders_before = find_placeholders(merged)

    replaced = replace_placeholders(merged, mapping)
    placeholders_after = find_placeholders(replaced)

    cleaned, modified_p_ids = remove_line_seg_arrays_for_modified_paragraphs(
        before_xml=merged, after_xml=replaced
    )

    xml_path.write_text(cleaned, "utf-8")
    return XmlChangeReport(
        path=xml_path,
        placeholders_before=placeholders_before,
        placeholders_after=placeholders_after,
        modified_paragraph_ids=modified_p_ids,
    )


def scan_for_remaining_placeholders(base_dir: Path) -> List[Tuple[Path, List[str]]]:
    remaining: List[Tuple[Path, List[str]]] = []
    for p in base_dir.rglob("*.xml"):
        s = p.read_text("utf-8", errors="ignore")
        keys = find_placeholders(s)
        if keys:
            remaining.append((p, keys))
    return remaining


def main() -> None:
    if not TEMPLATE.exists():
        raise SystemExit(f"Missing template: {TEMPLATE}")
    if not JSON_PATH.exists():
        raise SystemExit(f"Missing JSON: {JSON_PATH}")

    data = json.loads(JSON_PATH.read_text("utf-8"))
    mapping = {k: transform_value(k, v) for k, v in data.items()}

    extract_hwpx(TEMPLATE, WORK_DIR)

    # Find XML files that contain placeholders.
    xml_files = []
    for p in WORK_DIR.rglob("*.xml"):
        s = p.read_text("utf-8", errors="ignore")
        if "{{" in s:
            xml_files.append(p)

    reports: List[XmlChangeReport] = []
    for p in sorted(xml_files):
        reports.append(process_xml_file(p, mapping))

    remaining = scan_for_remaining_placeholders(WORK_DIR)
    if remaining:
        details = "\n".join(
            f"- {p.relative_to(WORK_DIR)}: {keys}" for p, keys in remaining
        )
        raise SystemExit(f"Remaining placeholders found after replacement:\n{details}")

    repack_hwpx(WORK_DIR, OUT_PATH)

    # Validate output ZIP and ensure no placeholders remain.
    if not OUT_PATH.exists():
        raise SystemExit(f"Output not created: {OUT_PATH}")
    if not zipfile.is_zipfile(OUT_PATH):
        raise SystemExit("Output is not a valid ZIP/HWPX")

    extract_hwpx(OUT_PATH, VERIFY_DIR)
    remaining2 = scan_for_remaining_placeholders(VERIFY_DIR)
    if remaining2:
        details = "\n".join(
            f"- {p.relative_to(VERIFY_DIR)}: {keys}" for p, keys in remaining2
        )
        raise SystemExit(f"Remaining placeholders in output:\n{details}")

    # Sanity checks for required formatting.
    all_xml_text = "\n".join(p.read_text("utf-8", errors="ignore") for p in VERIFY_DIR.rglob("*.xml"))

    expected_attendees = mapping.get("참석자수")
    expected_score = mapping.get("만족도")
    expected_suffix = "후속 심화반 검토 요망."

    if expected_attendees and expected_attendees not in all_xml_text:
        raise SystemExit(f"Expected 참석자수 value not found: {expected_attendees}")
    if expected_score and expected_score not in all_xml_text:
        raise SystemExit(f"Expected 만족도 value not found: {expected_score}")
    if expected_suffix not in all_xml_text:
        raise SystemExit("Expected 종합의견 suffix not found")

    print("OK")
    print(f"Wrote: {OUT_PATH}")
    for r in reports:
        rel = r.path.relative_to(WORK_DIR)
        print(f"- {rel}: replaced {len(r.placeholders_before)} keys; modified paragraphs: {len(r.modified_paragraph_ids)}")


if __name__ == "__main__":
    main()

